import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, unlinkSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

// Generated files are committed; ordinary builds need no image encoder.
const manifest = { velvet: {}, meme: {} };
let before = 0, after = 0;
const encode = (source, directory, name, options) => {
  const input = resolve('public', source), folder = resolve('public', directory);
  mkdirSync(folder, { recursive: true });
  const temporary = resolve(folder, name + '.webp');
  execFileSync(process.env.CWEBP || 'cwebp', ['-quiet', ...options, input, '-o', temporary]);
  const bytes = readFileSync(temporary), hash = createHash('sha256').update(bytes).digest('hex').slice(0, 12);
  const filename = `${name}-${hash}.webp`;
  writeFileSync(resolve(folder, filename), bytes); unlinkSync(temporary);
  before += readFileSync(input).length; after += bytes.length;
  return '/' + directory + '/' + filename;
};
// These portraits appear in held reel columns and have no full-resolution viewer.
// 640x960 covers their visible height at twice the usual game window density.
for (const name of ['evelyn', 'celeste', 'mei', 'viola', 'amira']) {
  manifest.velvet[name] = encode(`assets/velvet-rebuild/v2/${name}.webp`, 'assets/velvet-rebuild/v3', name,
    ['-q', '92', '-alpha_q', '100', '-m', '6', '-resize', '640', '960']);
}
manifest.meme.stonks = encode('assets/meme-overload/v1/stonks.png', 'assets/meme-overload/v2', 'stonks',
  ['-lossless', '-exact', '-z', '6']);
writeFileSync('src/ui/slotKit/nativeSlotImages.ts', '// Generated by scripts/build-native-slot-images.mjs.\n' + Object.entries(manifest.velvet).map(([name,url]) => `export const velvet${name[0].toUpperCase()+name.slice(1)} = ${JSON.stringify(url)};`).join('\n') + `\nexport const memeStonks = ${JSON.stringify(manifest.meme.stonks)};\n`);
console.log(JSON.stringify({ before, after, savedBytes: before - after, images: manifest }));
